"""Richer differential mutation campaign on both reference and captured images."""
import copy, json, random, sys
sys.path.insert(0, '/workspace/tmp')
import cli, pyref
from test_mutate import load_verdict, py_verdict, shape_ok

binary = cli.build()
rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1234)


def mutate(rng, img):
    img = copy.deepcopy(img)
    kind = rng.choice(['flip', 'flip', 'flip', 'setword', 'duprow', 'swaprows', 'delrow', 'bitmaps_swap',
                       'ni_ins', 'ni_del', 'ni_reorder', 'front_move', 'root_move', 'cells_tweak', 'shift'])
    s = rng.randrange(11)
    if not img['banks'][s]:
        return img if kind in ('bitmaps_swap', 'ni_ins', 'ni_del', 'ni_reorder', 'root_move') else None
    r = rng.randrange(len(img['banks'][s]))
    w = int(img['banks'][s][r], 16)
    if kind == 'flip':
        for _ in range(rng.randint(1, 3)):
            w ^= 1 << rng.randrange(256)
        img['banks'][s][r] = format(w, '064x')
    elif kind == 'setword':
        img['banks'][s][r] = format(rng.getrandbits(256), '064x')
    elif kind == 'duprow':
        s2 = rng.randrange(11)
        if img['banks'][s2]:
            img['banks'][s][r] = img['banks'][s2][rng.randrange(len(img['banks'][s2]))]
    elif kind == 'swaprows':
        r2 = rng.randrange(len(img['banks'][s]))
        img['banks'][s][r], img['banks'][s][r2] = img['banks'][s][r2], img['banks'][s][r]
    elif kind == 'delrow':
        if img['banks'][s] and img['cells'][s] >= 2:
            img['banks'][s].pop(r)
            img['cells'][s] -= 2
    elif kind == 'bitmaps_swap':
        b = img['bitmaps']
        if len(b) >= 2:
            i, j = rng.randrange(len(b)), rng.randrange(len(b))
            b[i], b[j] = b[j], b[i]
    elif kind == 'ni_ins':
        img['nexthops'].insert(rng.randrange(len(img['nexthops']) + 1), rng.randint(0, 4194302))
    elif kind == 'ni_del':
        if img['nexthops']:
            img['nexthops'].pop(rng.randrange(len(img['nexthops'])))
    elif kind == 'ni_reorder':
        n = img['nexthops']
        if len(n) >= 2:
            i, j = rng.randrange(len(n)), rng.randrange(len(n))
            n[i], n[j] = n[j], n[i]
    elif kind == 'front_move':
        pool = img['front16'] or img['front64']
        if len(pool) >= 2:
            i, j = rng.randrange(len(pool)), rng.randrange(len(pool))
            pool[i], pool[j] = pool[j], pool[i]
    elif kind == 'root_move':
        if img['root'] is not None:
            pool = img['front16'] or img['front64']
            if pool:
                img['root'] = [pool[0][1], pool[0][2]]
    elif kind == 'cells_tweak':
        if img['cells'][s] >= 2:
            img['cells'][s] -= 2
    elif kind == 'shift':
        s2 = rng.randrange(11)
        if img['banks'][s2] and img['cells'][s2] >= 2:
            img['banks'][s2].insert(rng.randrange(len(img['banks'][s2]) + 1), img['banks'][s][r])
            img['cells'][s2] += 2
    return img


def campaign(base, label, rounds=120):
    bad = 0
    acc = rej = 0
    for m in range(rounds):
        img = mutate(rng, base)
        if img is None:
            continue
        if not shape_ok(img):
            continue
        c = load_verdict(binary, img)
        p = py_verdict(img)
        if c == 'invalid-request':
            continue
        if c is True: acc += 1
        else: rej += 1
        if (c is True) != (p is True):
            print('DISAGREE', label, 'cpp', c, 'py', p)
            json.dump({'img': img, 'base': base}, open('dis_%s_%d.json' % (label, m), 'w'))
            bad += 1
    print('%s: accepted=%d rejected=%d disagreements=%d' % (label, acc, rej, bad))
    return bad


# base 1: python reference image of a rich FIB
d = {}
def add(hi, lo, ln):
    hi, lo = pyref.norm(hi, lo, ln)
    d[(hi, lo, ln)] = rng.randint(0, 4194302)
base = 0x20010db812345678
for i in range(70): add(base, (i & 63) << 58, 70)
for i in range(40): add(base, (i << 50) | 7, 128)
for i in range(20): add((base >> 16) | (i << 48), 0x1234, 34)
for i in range(14): add(i << 60, 0, 12)
add(0, 0, 0); add(0x000000ff << 48, 0, 16)
prefixes = sorted([(k[0], k[1], k[2], v) for k, v in d.items()])
py_img = pyref.build_image(prefixes, rng)
fails = campaign(py_img, 'pyref-image')

# base 2: image captured by the C++ exporter
ops = [['put', '%016x%016x' % (k[0], k[1]), k[2], v] for k, v in d.items()] + [['save']]
res = cli.results({'cases': [{'ops': ops}]}, binary)[0]
cpp_img = res['snapshots'][0]
fails += campaign(cpp_img, 'cpp-capture')
sys.exit(1 if fails else 0)
